//! Pair lifecycle. No certificate is generated by `new`/startup; only `create_pair` signs.

use crate::storage::{PkiRecord, Storage};

use super::{
    build_download_bundle, generate_pair, now_secs, random_id, valid_name, valid_server_name,
    DownloadBundle, PkiConfig, PkiError, PkiFiles, PkiRepository, PkiRuntime, PkiStatus,
};

#[derive(Clone)]
pub struct PkiService {
    files: PkiFiles,
    repo: PkiRepository,
    runtime: PkiRuntime,
    config: PkiConfig,
}

impl PkiService {
    /// Open the file store and eagerly load all previously persisted active pairs.
    /// This must not generate a CA or certificate.
    pub fn new(config: PkiConfig, store: Storage) -> Result<Self, PkiError> {
        config.validate()?;
        let service = Self {
            files: PkiFiles::new(config.dir.clone()),
            repo: PkiRepository::new(store),
            runtime: PkiRuntime::default(),
            config,
        };
        service.load_active_pairs()?;
        Ok(service)
    }

    pub fn server_config(&self) -> Result<std::sync::Arc<rustls::ServerConfig>, PkiError> {
        self.runtime.server_config()
    }

    pub fn config(&self) -> &PkiConfig {
        &self.config
    }

    pub fn status(&self) -> Result<PkiStatus, PkiError> {
        let active = self.active_records()?;
        Ok(PkiStatus {
            enabled: self.config.enabled,
            credentials: active.len(),
            tunnel_ready: self.runtime.tunnel_ready(),
            waiting_for_credentials: active.is_empty(),
        })
    }

    pub fn list(&self, tenant_id: Option<&str>) -> Result<Vec<PkiRecord>, PkiError> {
        let mut records = self.repo.list(tenant_id)?;
        for record in &mut records {
            if record.status != "revoked" && record.client_not_after <= now_secs() {
                record.status = "expired".to_string();
            } else if record.status == "waiting" && record.last_connected_at.is_some() {
                record.status = "connected".to_string();
            }
        }
        Ok(records)
    }

    pub fn active_records(&self) -> Result<Vec<PkiRecord>, PkiError> {
        Ok(self
            .list(None)?
            .into_iter()
            .filter(|r| r.status == "waiting" || r.status == "connected")
            .collect())
    }

    fn load_active_pairs(&self) -> Result<(), PkiError> {
        for record in self.active_records()? {
            let loaded = self
                .files
                .load_pair(&record.id, &record.server_name)
                .map_err(|e| match e {
                    PkiError::Io(err) => PkiError::Storage(format!(
                        "active pair {} cannot be loaded: {err}",
                        record.id
                    )),
                    other => other,
                })?;
            let key = loaded.certified_key()?;
            self.runtime
                .add_pair(&record.server_name, &record.id, key, loaded.ca_cert.clone())?;
        }
        Ok(())
    }

    pub fn create_pair(
        &self,
        name: &str,
        tenant_id: &str,
        server_name: &str,
        server_sans: &[String],
        created_by: &str,
        ca_common_name: &str,
    ) -> Result<PkiRecord, PkiError> {
        if !valid_name(name) {
            return Err(PkiError::Invalid(
                "name must be 1..=64 chars of [a-z0-9-]".into(),
            ));
        }
        if !valid_server_name(server_name) {
            return Err(PkiError::Invalid(
                "server_name must be a lowercase DNS name (not an IP)".into(),
            ));
        }
        if !server_sans.iter().any(|s| s == server_name) {
            return Err(PkiError::Invalid(
                "server_sans must contain server_name".into(),
            ));
        }
        let existing = self.list(None)?;
        if existing.iter().any(|r| {
            (r.status == "waiting" || r.status == "connected")
                && (r.server_name == server_name || (r.tenant_id == tenant_id && r.name == name))
        }) {
            return Err(PkiError::Conflict(
                "an active pair already uses this name or server_name".into(),
            ));
        }

        let id = random_id();
        let generated = generate_pair(
            &self.config,
            &id,
            name,
            tenant_id,
            server_name,
            server_sans,
            ca_common_name,
        )?;
        self.files.write_pair(&generated)?;
        let loaded = match self.files.load_pair(&id, server_name) {
            Ok(v) => v,
            Err(e) => {
                self.files.remove_pair(&id);
                return Err(e);
            }
        };
        let key = match loaded.certified_key() {
            Ok(v) => v,
            Err(e) => {
                self.files.remove_pair(&id);
                return Err(e);
            }
        };
        let record = PkiRecord {
            id: id.clone(),
            name: name.to_string(),
            tenant_id: tenant_id.to_string(),
            server_name: server_name.to_string(),
            ca_fingerprint_sha256: generated.ca_fingerprint_sha256,
            server_fingerprint_sha256: generated.server_fingerprint_sha256,
            client_fingerprint_sha256: generated.client_fingerprint_sha256,
            serial: generated.serial,
            status: "waiting".into(),
            created_at: now_secs(),
            created_by: created_by.to_string(),
            downloaded_at: None,
            last_connected_at: None,
            revoked_at: None,
            client_not_after: generated.client_not_after,
        };
        if let Err(e) = self.repo.insert(&record) {
            self.files.remove_pair(&id);
            return Err(e);
        }
        if let Err(e) = self
            .runtime
            .add_pair(server_name, &id, key, loaded.ca_cert.clone())
        {
            let _ = self.repo.delete(&id);
            self.files.remove_pair(&id);
            return Err(e);
        }
        if !self.runtime.has_server(server_name) {
            let _ = self.repo.delete(&id);
            self.files.remove_pair(&id);
            return Err(PkiError::Storage(
                "server certificate did not become resolvable".into(),
            ));
        }
        Ok(record)
    }

    pub fn record(&self, id: &str) -> Result<PkiRecord, PkiError> {
        self.repo.get(id)?.ok_or(PkiError::NotFound)
    }

    pub fn mark_connected(&self, server_name: &str) -> Result<(), PkiError> {
        if let Some(id) = self.runtime.pair_id_for_server(server_name) {
            self.repo.mark_connected(&id, now_secs())?;
        }
        Ok(())
    }

    pub fn download(&self, id: &str) -> Result<DownloadBundle, PkiError> {
        let record = self.record(id)?;
        if record.status == "revoked" || record.revoked_at.is_some() {
            return Err(PkiError::NotFound);
        }
        if record.client_not_after <= now_secs() {
            return Err(PkiError::Expired);
        }
        if record.downloaded_at.is_some() {
            return Err(PkiError::DownloadConsumed);
        }
        let key = self.files.load_client_key(id)?;
        let ca = self.files.load_pair(&record.id, &record.server_name)?;
        let bundle = build_download_bundle(
            &record.name,
            &record.server_name,
            &ca.ca_cert_pem,
            &ca.client_cert_pem,
            &key,
        )?;
        self.repo.mark_downloaded(id, now_secs())?;
        self.files.remove_client_key(id)?;
        Ok(bundle)
    }

    pub fn revoke(&self, id: &str) -> Result<(), PkiError> {
        let record = self.record(id)?;
        if record.status == "revoked" {
            return Err(PkiError::Conflict("pair is already revoked".into()));
        }
        let loaded = self
            .files
            .load_pair(&record.id, &record.server_name)
            .map_err(|e| PkiError::Storage(format!("cannot revoke pair {id}: {e}")))?;
        let client_cert = loaded.client_cert()?;
        self.runtime
            .remove_pair(&record.server_name, &loaded.ca_cert, &client_cert)?;
        self.repo.revoke(id, now_secs())?;
        Ok(())
    }
}
